fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure the two input vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Compare element‐wise after converting to i32 and collect the results
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| (x as i32) > (y as i32))
     .collect()
}

